{
  "references": [
    {
      "id": "R1",
      "summary_ko": "여성이 벽에 손을 뻗어 만지는 동작이 부자연스러움."
    },
    {
      "id": "R2",
      "summary_ko": "프롬프트의 지시와 달리 여성이 장면 내 누구와도 상호작용하지 않음."
    },
    {
      "id": "R3",
      "summary_ko": "완전히 반대 방향이자 도시의 다른 구역에서 두 개의 거대한 불꽃놀이가 동시에 열리는 비현실적인 현상."
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "영상 특징과 픽셀 구조의 변화로 형태 및 존재 변화 가능성을 감지한 측정 제안."
    },
    {
      "id": "C2",
      "summary_ko": "카메라가 빠르게 회전할 때 인물의 얼굴과 상체가 심하게 왜곡되며 벽 질감 속으로 녹아듦."
    },
    {
      "id": "C3",
      "summary_ko": "카메라가 패닝하며 움직임을 추적할 때 여성의 머리, 이목구비, 신체 형태가 크게 왜곡됨."
    },
    {
      "id": "C4",
      "summary_ko": "불꽃놀이가 불규칙한 확장 패턴, 깜빡이는 궤적, 부자연스러운 반복/재폭발 양상을 보임."
    },
    {
      "id": "C5",
      "summary_ko": "배경 보행자들의 사지 움직임 불일치, 형태 왜곡 및 불규칙한 걸음걸이 속도."
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "C1은 구체적 대상이 없는 일반 측정 제안으로, R1의 벽을 만지는 부자연스러운 동작과 연관될 가능성이 있으나 정보가 부족함."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "R1은 벽에 손을 뻗는 동작의 부자연스러움을 지적하는 반면, C2는 얼굴과 상체가 벽 질감으로 왜곡·용해되는 현상을 다룸."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "R1은 벽을 만지는 손 동작의 이상을 다루는 반면, C3는 전반적인 신체 및 얼굴 형태의 왜곡을 설명함."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C4",
      "verdict": "different",
      "reason_ko": "R1은 인물의 손동작에 관한 것이고, C4는 불꽃놀이의 시각적 이상에 관한 것으로 대상이 완전히 다름."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C5",
      "verdict": "different",
      "reason_ko": "R1은 주 인물이 벽을 만지는 동작에 대한 것이며, C5는 배경 보행자들의 사지 왜곡에 관한 것임."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "C1은 미식별된 화면 변화에 대한 제안으로, R2의 프롬프트 불일치(상호작용 부재)와 동일한지 판단하기 어려움."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "R2는 타인과의 상호작용 부재를 언급하고, C2는 카메라 회전 시 신체 형태의 왜곡 및 질감 용해를 다룸."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "R2는 상호작용 부재에 대한 지적이며, C3는 신체와 얼굴 형태의 물리적 변형 및 왜곡을 다룸."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C4",
      "verdict": "different",
      "reason_ko": "R2는 인물의 상호작용 결여에 관한 내용이고, C4는 불꽃놀이의 비정상적 움직임에 관한 것임."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C5",
      "verdict": "different",
      "reason_ko": "R2는 인물의 상호작용 부재를 다루며, C5는 배경 보행자들의 사지 움직임 및 형태 왜곡을 다룸."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "C1은 대상이 식별되지 않은 측정 제안이므로 R3의 불꽃놀이 위치적 모순과 동일한 현상인지 판별할 수 없음."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "R3는 불꽃놀이의 공간적 이상에 관한 것이고, C2는 보행 여성의 신체 왜곡에 관한 것임."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "R3는 불꽃놀이 배치 오류에 관한 것이고, C3는 여성의 형태 왜곡에 관한 것임."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C4",
      "verdict": "different",
      "reason_ko": "동일한 불꽃놀이를 다루지만, R3는 서로 다른 방향에서 두 개의 쇼가 열리는 상황적 모순을 지적하는 반면 C4는 개별 불꽃의 불규칙한 확장 및 깜빡임 등 형태적 결함을 다룸."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C5",
      "verdict": "different",
      "reason_ko": "R3는 불꽃놀이에 관한 내용이고, C5는 배경 보행자들의 이상 움직임에 관한 것임."
    }
  ]
